			controls.failNext = true;
		},
		setSaveMode(value) {
			controls.save = value;
		},
		dispose() {
			if (disposed) return;
			disposed = true;
			owned.host.workflow.dispose();
			owned.selection.dispose();
			session.dispose();
			session.runtime.invalidate();
			scope.stop();
			textScope.dispose();
		}
	};
}

/** 前端项目表单投影；记录原类型与宿主补充数据分别保留。 */
export function projectFormModel(row, reference, project) {
	return {
		title: row.title,
		reference,
		category: row.category,
		owner: String(row.owner ?? ''),
		status: row.status,
		...project,
		channels: [...project.channels],
		tags: [...project.tags],
		files: project.files.map((file) => ({ ...file })),
		description: row.description
	};
}

/** 项目示例的显示映射；保留未知值和 typed 原值，不作为通用业务字典。 */
export function projectStatusType(status) {
	switch (status) {
		case '进行中':
		case '处理中':
			return 'primary';
		case '已完成':
		case '启用':
		case '已发布':
		case '已审核':
			return 'success';
		case '待启动':
		case '待启用':
		case '待处理':
		case '待审核':
		case '未确定':
			return 'warning';
		case '失败':
		case '错误':
		case '拒绝':
		case '驳回':
			return 'danger';
		default:
			return 'info';
	}
}

import { computed, shallowRef, watch } from 'vue';
